constexpr int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

// Guaranteed compile-time evaluation
constexpr int FACT_5 = factorial(5);

// Run-time evaluation (if input is dynamic)
int N = 5;
int result_rt = factorial(N);


struct Vec3 {
    const int x, y, z;
    constexpr Vec3(int a, int b, int c) : x(a), y(b), z(c) {}
    constexpr int sum() const { return x + y + z; }
};

constexpr Vec3 V(1, 2, 3);
constexpr int CT_SUM = V.sum();

